import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    counts = Counter(a)

    for count in counts.values():
        if count > 2:
            print("NO")
            return

    inc = []
    dec = []

    for x in sorted(counts.keys()):
        if counts[x] == 2:
            inc.append(x)
            dec.append(x)
        elif counts[x] == 1:
            if not inc or x > inc[-1]:
                inc.append(x)
            else:
                dec.append(x)

    dec.sort(reverse=True)

    print("YES")
    print(len(inc))
    print(*(inc))
    print(len(dec))
    print(*(dec))

if __name__ == "__main__":
    solve()
